/**
 * Generates the platform entry modules (`build/platforms/*.gen.js`) from the
 * vite-plugin-bem-levels scan registry (design doc, Key Components 8 / D-8).
 *
 * The generated files are committed lockfile-style: CI re-runs this generator
 * and diffs (freshness), so the artifact cannot rot the way the hand-maintained
 * lists did. Imports are emitted in canonical sorted order — sound because
 * cross-module ordering is carried by static `bem:` import edges, not list
 * order.
 *
 * Payload parity against the pre-S0 hand lists (including `keyboard__codes`)
 * is asserted by `test/platform-entries.test.js` against
 * `specs/pre-s0-platforms-{desktop,touch}.txt`.
 */

import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { buildRegistry } from './plugins/vite-plugin-bem-levels.js';

const rootDir = resolve(import.meta.dirname, '..');

const PLATFORM_LEVELS = {
    desktop: ['common.blocks', 'desktop.blocks'],
    touch: ['common.blocks', 'touch.blocks'],
};

for (const [platform, levels] of Object.entries(PLATFORM_LEVELS)) {
    const registry = buildRegistry(levels, rootDir);
    const names = [...registry.modules.keys()]
        .filter((name) => {
            const entries = registry.modules.get(name);
            return entries && entries.length > 0;
        })
        .sort();

    const lines = [
        '// @generated by build/generate-platform-entries.mjs — DO NOT EDIT.',
        `// Platform entry for the ${platform} platform, generated from the`,
        '// vite-plugin-bem-levels scan registry. Regenerate with:',
        '//     node build/generate-platform-entries.mjs',
        '// Imports are in canonical sorted order; cross-module ordering rides',
        '// static bem: import edges, not list order.',
        '',
        `// ${platform}: ${names.length} modules`,
        '',
    ];
    for (const name of names) {
        lines.push(`import 'bem:${name}';`);
    }

    const outPath = resolve(rootDir, 'build', 'platforms', `${platform}.gen.js`);
    writeFileSync(outPath, lines.join('\n') + '\n');
    console.log(`${platform}: ${names.length} modules -> build/platforms/${platform}.gen.js`);
}
